from pathlib import Path
R=Path('apps/web/src');A=R/'app';C=R/'components'
(C/'operation-form.tsx').write_text('''"use client";
import {useActionState} from "react";
export function OperationForm({action,children,label="Guardar",danger=false}:{action:(state:string,form:FormData)=>Promise<string>;children:React.ReactNode;label?:string;danger?:boolean}){const [message,submit,pending]=useActionState(action,"");return <form action={submit} onSubmit={e=>{if(danger&&!confirm("¿Confirmas esta eliminación? La operación puede ser rechazada si existen registros relacionados."))e.preventDefault();}} className="space-y-3 rounded-xl border border-slate-200 bg-white p-5">{children}<button disabled={pending} className="rounded-lg bg-blue-700 px-5 py-3 text-white disabled:opacity-50">{pending?"Procesando…":label}</button>{message&&<p role="status" className="text-sm">{message}</p>}</form>}
''')
(A/'panel/asignaturas').mkdir(parents=True,exist_ok=True)
(A/'panel/asignaturas/actions.ts').write_text('''"use server";
import {requireProfile} from "@/lib/auth";
import {canManage} from "@/lib/management-validation";
import {revalidatePath} from "next/cache";
export async function subjectAction(_:string,form:FormData){const {supabase,profile}=await requireProfile();if(!canManage(profile.rol))return "Sin permiso.";const id=String(form.get("id")||"");const op=form.get("op");const nombre=String(form.get("nombre")||"").trim();if(op!=="delete"&&(!nombre||nombre.length>150))return "Escribe un nombre de hasta 150 caracteres.";let result;if(op==="delete")result=await supabase.from("asignaturas").delete().eq("id",id).select("id");else if(id)result=await supabase.from("asignaturas").update({nombre,descripcion:String(form.get("descripcion")||"").slice(0,1000),activo:form.get("activo")==="on"}).eq("id",id).eq("updated_at",String(form.get("version"))).select("id");else result=await supabase.from("asignaturas").insert({nombre,descripcion:String(form.get("descripcion")||"").slice(0,1000)}).select("id");if(result.error)return "No se pudo guardar: revisa duplicados, permisos o registros relacionados.";if(!result.data?.length)return "El registro cambió o no está disponible. Recarga la página.";revalidatePath("/panel/asignaturas");return "Operación completada.";}
''')
(A/'panel/asignaturas/page.tsx').write_text('''import {requireProfile} from "@/lib/auth";
import {loadPanel} from "@/lib/data/live";
import {PanelShell} from "@/components/panel-shell";
import {OperationForm} from "@/components/operation-form";
import {subjectAction} from "./actions";
import {canManage} from "@/lib/management-validation";
export default async function Page(){const {supabase,profile}=await requireProfile();const admin=canManage(profile.rol);const assigned=await supabase.from("asignaciones_docente").select("asignatura_id").eq("activo",true);if(assigned.error)throw Error("No se pudieron consultar las asignaciones.");let query=supabase.from("asignaturas").select("*").order("nombre");if(!admin)query=query.in("id",assigned.data.map(a=>a.asignatura_id));const {data,error}=await query;if(error)throw Error("No se pudieron consultar las asignaturas.");return <PanelShell model={await loadPanel()}><h1 className="mb-6 text-3xl font-semibold">{admin?"Gestionar asignaturas":"Mis asignaturas"}</h1>{admin&&<OperationForm action={subjectAction} label="Registrar asignatura"><label className="block">Nombre<input required name="nombre" maxLength={150} className="block w-full rounded border p-3"/></label><label className="block">Descripción<textarea name="descripcion" className="block w-full rounded border p-3"/></label></OperationForm>}<div className="mt-6 grid gap-5 md:grid-cols-2">{data.map(s=>admin?<section key={s.id}><OperationForm action={subjectAction}><input type="hidden" name="id" value={s.id}/><input type="hidden" name="version" value={s.updated_at}/><label className="block">Asignatura<input required name="nombre" defaultValue={s.nombre} className="block w-full rounded border p-3"/></label><label className="block">Descripción<textarea name="descripcion" defaultValue={s.descripcion||""} className="block w-full rounded border p-3"/></label><label><input type="checkbox" name="activo" defaultChecked={s.activo}/> Activa</label></OperationForm><OperationForm action={subjectAction} danger label="Eliminar asignatura"><input type="hidden" name="id" value={s.id}/><input type="hidden" name="op" value="delete"/></OperationForm></section>:<article key={s.id} className="rounded-xl border bg-white p-6"><h2 className="text-xl font-semibold">{s.nombre}</h2><p>{s.descripcion}</p></article>)}</div>{!data.length&&<p className="mt-6">No hay asignaturas vinculadas a tu cuenta.</p>}</PanelShell>}
''')
(A/'panel/usuarios').mkdir(parents=True,exist_ok=True)
(A/'panel/usuarios/actions.ts').write_text('''"use server";
import {requireProfile} from "@/lib/auth";
import {canManage,uuidPattern} from "@/lib/management-validation";
import {isRole} from "@iberdrola/shared";
import {createClient} from "@supabase/supabase-js";
import {revalidatePath} from "next/cache";
export async function accountAction(_:string,form:FormData){const {supabase,profile,user}=await requireProfile();if(!canManage(profile.rol))return "Sin permiso.";const op=String(form.get("op")||"create"),id=String(form.get("id")||""),rol=String(form.get("rol")||""),persona=String(form.get("persona")||"");if(op!=="delete"&&!isRole(rol))return "Selecciona un rol válido.";if(profile.rol==="SECRETARIA"&&["DIRECTOR","SECRETARIA"].includes(rol))return "Secretaría solo gestiona cuentas de docentes, estudiantes y familias.";if(id===user.id)return "No puedes modificar ni eliminar tu propia cuenta desde este formulario.";if(op!=="create"&&!uuidPattern.test(id))return "Cuenta inválida.";
const url=process.env.NEXT_PUBLIC_SUPABASE_URL,secret=process.env.SUPABASE_SECRET_KEY;if(op==="create"){
if(!uuidPattern.test(persona))return "Selecciona una persona.";if(!url||!secret)return "Configura SUPABASE_SECRET_KEY solo en el servidor para invitar cuentas.";
const email=String(form.get("email")||"").trim();if(!/^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/.test(email))return "Correo inválido.";
const admin=createClient(url,secret,{auth:{persistSession:false,autoRefreshToken:false}});const invited=await admin.auth.admin.inviteUserByEmail(email,{redirectTo:process.env.NEXT_PUBLIC_SITE_URL?`${process.env.NEXT_PUBLIC_SITE_URL}/auth/callback`:undefined});if(invited.error||!invited.data.user)return "No se pudo invitar: verifica que la cuenta no exista y la configuración de correo.";
const result=await supabase.rpc("administrar_cuenta" as never,{p_id:invited.data.user.id,p_persona:persona,p_rol:rol,p_activo:true,p_eliminar:false} as never);if(result.error){await admin.auth.admin.deleteUser(invited.data.user.id);return "No se pudo vincular la cuenta. Verifica que exista la ficha del rol seleccionado y que la persona no tenga otro perfil.";}
}else{const result=await supabase.rpc("administrar_cuenta" as never,{p_id:id,p_persona:null,p_rol:rol||"ESTUDIANTE",p_activo:form.get("activo")==="on",p_eliminar:op==="delete"} as never);if(result.error)return "Operación rechazada: cuenta protegida, ficha incompatible o dependencias. El administrador no puede eliminarse a sí mismo.";}
revalidatePath("/panel/usuarios");return op==="delete"?"Acceso institucional eliminado. La identidad de autenticación se conserva para auditoría.":"Cuenta guardada. Las cuentas nuevas reciben un correo de invitación.";}
''')
(A/'panel/usuarios/page.tsx').write_text('''import {requireProfile} from "@/lib/auth";
import {loadPanel} from "@/lib/data/live";
import {PanelShell} from "@/components/panel-shell";
import {OperationForm} from "@/components/operation-form";
import {accountAction} from "./actions";
import {canManage} from "@/lib/management-validation";
import {roles,roleLabels} from "@iberdrola/shared";
import {notFound} from "next/navigation";
export default async function Page(){const {supabase,profile,user}=await requireProfile();if(!canManage(profile.rol))notFound();const [people,accounts]=await Promise.all([supabase.from("personas").select("id,nombres,apellido_paterno,apellido_materno").order("nombres"),supabase.from("perfiles").select("*").order("created_at")]);if(people.error||accounts.error)throw Error("No se pudieron consultar las cuentas.");const allowed=roles.filter(r=>profile.rol==="DIRECTOR"||!["DIRECTOR","SECRETARIA"].includes(r));const name=(id:string)=>{const p=people.data.find(x=>x.id===id);return p?[p.nombres,p.apellido_paterno,p.apellido_materno].filter(Boolean).join(" "):"Persona no disponible";};return <PanelShell model={await loadPanel()}><h1 className="mb-4 text-3xl font-semibold">Gestionar usuarios</h1><p className="mb-6">Registra primero la ficha de estudiante, docente o tutor. Después invita su cuenta y asigna el rol correspondiente.</p><OperationForm action={accountAction} label="Invitar usuario"><label className="block">Persona<select required name="persona" className="block w-full border p-3"><option value="">Seleccionar persona</option>{people.data.filter(p=>!accounts.data.some(a=>a.persona_id===p.id)).map(p=><option key={p.id} value={p.id}>{name(p.id)}</option>)}</select></label><label className="block">Correo<input required type="email" name="email" className="block w-full border p-3"/></label><label className="block">Rol<select name="rol" className="block w-full border p-3">{allowed.map(r=><option key={r} value={r}>{roleLabels[r]}</option>)}</select></label></OperationForm><div className="mt-8 grid gap-4 md:grid-cols-2">{accounts.data.filter(a=>allowed.includes(a.rol)).map(a=><article key={a.id}><h2 className="mb-2 text-lg font-semibold">{name(a.persona_id)}</h2>{a.id===user.id?<p>Tu cuenta · {roleLabels[a.rol]}</p>:<><OperationForm action={accountAction}><input name="id" type="hidden" value={a.id}/><input name="op" type="hidden" value="update"/><label>Rol<select name="rol" defaultValue={a.rol} className="block w-full border p-3">{allowed.map(r=><option key={r} value={r}>{roleLabels[r]}</option>)}</select></label><label><input type="checkbox" name="activo" defaultChecked={a.activo}/> Cuenta activa</label></OperationForm><OperationForm action={accountAction} danger label="Eliminar acceso"><input name="id" type="hidden" value={a.id}/><input name="op" type="hidden" value="delete"/></OperationForm></>}</article>)}</div></PanelShell>}
''')
